  const d = (a, b) => (a != null && b != null) ? +(a - b).toFixed(2) : null;
  const dAsing = kini && lalu ? d(kini.asing, lalu.asing) : null, dInst = kini && lalu ? d(kini.inst, lalu.inst) : null, dRitel = kini && lalu ? d(kini.ritel, lalu.ritel) : null;
