  if (uangBesarMasuk) { alasan.push(`porsi ${dAsing != null && dAsing >= 0.3 ? 'asing' : 'institusi lokal'} naik ${(Math.max(dAsing || 0, dInst || 0)).toFixed(2)} poin sebulan`); if (!tone) { vonis = 'UANG BESAR MASUK'; tone = 'good'; } }
